/* 006-plugins-contact-form-7-includes-css-styles.css */
.egl .wpcf7 .screen-reader-response {
	position: absolute;
	overflow: hidden;
	clip: rect(1px, 1px, 1px, 1px);
	clip-path: inset(50%);
	height: 1px;
	width: 1px;
	margin: -1px;
	padding: 0;
	border: 0;
	word-wrap: normal !important;
	word-break: normal !important;
}

.egl .wpcf7 .hidden-fields-container {
	display: none;
}

.egl .wpcf7 form .wpcf7-response-output {
	margin: 2em 0.5em 1em;
	padding: 0.2em 1em;
	border: 2px solid #00a0d2; /* Blue */
}

.egl .wpcf7 form.init .wpcf7-response-output,
.egl .wpcf7 form.resetting .wpcf7-response-output,
.egl .wpcf7 form.submitting .wpcf7-response-output {
	display: none;
}

.egl .wpcf7 form.sent .wpcf7-response-output {
	border-color: #46b450; /* Green */
}

.egl .wpcf7 form.failed .wpcf7-response-output,
.egl .wpcf7 form.aborted .wpcf7-response-output {
	border-color: #dc3232; /* Red */
}

.egl .wpcf7 form.spam .wpcf7-response-output {
	border-color: #f56e28; /* Orange */
}

.egl .wpcf7 form.invalid .wpcf7-response-output,
.egl .wpcf7 form.unaccepted .wpcf7-response-output,
.egl .wpcf7 form.payment-required .wpcf7-response-output {
	border-color: #ffb900; /* Yellow */
}

.egl .wpcf7-form-control-wrap {
	position: relative;
}

.egl .wpcf7-not-valid-tip {
	color: #dc3232; /* Red */
	font-size: 1em;
	font-weight: normal;
	display: block;
}

.egl .use-floating-validation-tip .wpcf7-not-valid-tip {
	position: relative;
	top: -2ex;
	left: 1em;
	z-index: 100;
	border: 1px solid #dc3232;
	background: #fff;
	padding: .2em .8em;
	width: 24em;
}

.egl .wpcf7-list-item {
	display: inline-block;
	margin: 0 0 0 1em;
}

.egl .wpcf7-list-item-label::before,
.egl .wpcf7-list-item-label::after {
	content: " ";
}

.egl .wpcf7-spinner {
	visibility: hidden;
	display: inline-block;
	background-color: #23282d; /* Dark Gray 800 */
	opacity: 0.75;
	width: 24px;
	height: 24px;
	border: none;
	border-radius: 100%;
	padding: 0;
	margin: 0 24px;
	position: relative;
}

.egl form.submitting .wpcf7-spinner {
	visibility: visible;
}

.egl .wpcf7-spinner::before {
	content: '';
	position: absolute;
	background-color: #fbfbfc; /* Light Gray 100 */
	top: 4px;
	left: 4px;
	width: 6px;
	height: 6px;
	border: none;
	border-radius: 100%;
	transform-origin: 8px 8px;
	animation-name: spin;
	animation-duration: 1000ms;
	animation-timing-function: linear;
	animation-iteration-count: infinite;
}

@media (prefers-reduced-motion: reduce) {
	.egl .wpcf7-spinner::before {
		animation-name: blink;
		animation-duration: 2000ms;
	}
}

@keyframes spin {
	from {
		transform: rotate(0deg);
	}

	to {
		transform: rotate(360deg);
	}
}

@keyframes blink {
	from {
		opacity: 0;
	}

	50% {
		opacity: 1;
	}

	to {
		opacity: 0;
	}
}

.egl .wpcf7 [inert] {
	opacity: 0.5;
}

.egl .wpcf7 input[type="file"] {
	cursor: pointer;
}

.egl .wpcf7 input[type="file"]:disabled {
	cursor: default;
}

.egl .wpcf7 .wpcf7-submit:disabled {
	cursor: not-allowed;
}

.egl .wpcf7 input[type="url"],
.egl .wpcf7 input[type="email"],
.egl .wpcf7 input[type="tel"] {
